import React, { useState } from "react";
import { TouchableOpacity, View, ActivityIndicator } from "react-native";
import PropTypes from "prop-types";
import styles from "./index.styles";
import { Body } from "../../atoms/typography";
import strings from "../../utils/strings";
import { Icon } from "../../atoms/icons";
import colors from "../../styles/colors";

const Button = ({
  children,
  color,
  type,
  status,
  icon,
  iconPosition,
  loading,
  pressedBtn,
  onPress,
  testID,
}) => {
  const [pressed, setPressed] = useState(false);

  let styleButtonContainer = "";
  let styleButton = "";
  let styleText = styles.blackLabel;
  let styleButtonPressed = styles.primaryPressed;
  let colorIcon = colors.white;

  switch (type) {
    case strings.Button.type.primary:
      styleButtonContainer = styles.buttonContainer;
      styleButtonPressed = styles.primaryPressed;
      styleText = styles.whiteLabel;
      styleButton =
        status === strings.Button.status.disabled
          ? styles.primaryDisabled
          : styles.primary;
      colorIcon = colors.white;
      break;
    case strings.Button.type.secondary:
      styleButtonContainer = styles.buttonContainer;
      styleButtonPressed = styles.secondaryPressed;
      styleText =
        status === strings.Button.status.disabled
          ? styles.secondaryDisabledLabel
          : styles.primaryLabel;
      styleButton =
        status === strings.Button.status.disabled
          ? styles.secondaryDisabled
          : styles.secondary;
      colorIcon =
        status === strings.Button.status.disabled
          ? colors.primary100
          : colors.primary500;
      break;

    case strings.Button.type.tertiary:
      styleButtonContainer = styles.buttonLinkContainer;
      styleButtonPressed = styles.tertiaryPressed;
      styleText =
        status === strings.Button.status.disabled
          ? styles.tertiaryDisabledLabel
          : styles.tertiaryLabel;
      styleButton = styles.tertiary;
      colorIcon =
        status === strings.Button.status.disabled
          ? colors.neutral500
          : colors.neutral700;
      break;

    case strings.Button.type.basic:
      styleButtonContainer = styles.buttonContainer;
      styleButtonPressed = styles.basicPressed;
      styleText = styles.whiteLabel;
      styleButton =
        status === strings.Button.status.disabled
          ? styles.basicDisabled
          : styles.basic;
      colorIcon = colors.white;
      break;

    case strings.Button.type.outline:
      styleButtonContainer = styles.buttonContainer;
      styleButtonPressed = styles.outlinePressed;
      styleText =
        status === strings.Button.status.disabled
          ? styles.outlineDisabledLabel
          : styles.blackLabel;
      styleButton =
        status === strings.Button.status.disabled
          ? styles.outlineDisabled
          : styles.outline;
      colorIcon =
        status === strings.Button.status.disabled
          ? colors.neutral100
          : colors.neutral900;
      break;

    case strings.Button.type.destructive:
      styleButtonContainer = styles.buttonContainer;
      styleButtonPressed = styles.destructivePressed;
      styleText = styles.whiteLabel;
      styleButton =
        status === strings.Button.status.disabled
          ? styles.destructiveDisabled
          : styles.destructive;
      colorIcon = colors.white;
      break;
    case strings.Button.type.small:
      styleButtonContainer =
        iconPosition === "default"
          ? styles.buttonSmallContainer
          : iconPosition === "left"
          ? styles.buttonSmallLeftIConContainer
          : styles.buttonSmallRightIconContainer;
      styleButtonPressed = styles.basicPressed;
      styleText = styles.whiteLabel;
      styleButton = styles.basic;
      colorIcon = colors.white;
      break;
    case strings.Button.type.smallOutline:
      styleButtonContainer =
        iconPosition === "default"
          ? styles.buttonSmallOutlineContainer
          : iconPosition === "left"
          ? styles.buttonSmallOutlineLeftIConContainer
          : styles.buttonSmallOutlineRightIconContainer;
      styleButtonPressed =
        color === "white" ? styles.outlineWhitePressed : styles.outlinePressed;
      styleText =
        status === strings.Button.status.disabled
          ? styles.outlineDisabledLabel
          : color === "white"
          ? styles.whiteLabel
          : styles.blackLabel;
      styleButton =
        color === "white"
          ? styles.outlineWhite
          : status === strings.Button.status.disabled
          ? styles.outlineDisabled
          : styles.outline;
      colorIcon =
        color === "white"
          ? colors.white
          : status === strings.Button.status.disabled
          ? colors.neutral100
          : colors.neutral900;
      break;
    case strings.Button.type.fab:
      styleButtonContainer = children
        ? styles.buttonFabIconContainer
        : styles.buttonFabContainer;
      styleButtonPressed = styles.primaryPressed;
      styleText = styles.whiteLabel;
      styleButton = styles.primary;
      colorIcon = colors.white;
      break;
    case strings.Button.type.link:
      styleButtonContainer = styles.buttonLinkContainer;
      styleButtonPressed = styles.linkPressed;
      styleText =
        status === strings.Button.status.disabled
          ? styles.secondaryDisabledLabel
          : styles.primaryLabel;
      colorIcon =
        status === strings.Button.status.disabled
          ? colors.primary100
          : colors.primary500;
      break;
    case strings.Button.type.subLink:
      styleButtonContainer = styles.buttonLinkContainer;
      styleButtonPressed = styles.linkPressed;
      styleText =
        status === strings.Button.status.disabled
          ? styles.outlineDisabledLabel
          : styles.blackLabel;
      colorIcon =
        status === strings.Button.status.disabled
          ? colors.neutral100
          : colors.neutral900;
      break;
    case strings.Button.type.option:
      styleButtonContainer =
        iconPosition === "default"
          ? styles.buttonSmallOutlineContainer
          : iconPosition === "left"
          ? styles.buttonSmallOutlineLeftIConContainer
          : styles.buttonSmallOutlineRightIconContainer;
      styleButtonPressed = styles.option;
      styleText = styles.optionLabel;
      styleButton = styles.option;
      colorIcon =
        color === "white"
          ? colors.white
          : status === strings.Button.status.disabled
          ? colors.primary100
          : colors.primary500;
      break;
    case strings.Button.type.light:
      styleButtonContainer =
        iconPosition === "default"
          ? styles.buttonSmallOutlineContainer
          : iconPosition === "left"
          ? styles.buttonSmallOutlineLeftIConContainer
          : styles.buttonSmallOutlineRightIconContainer;
      styleButtonPressed = styles.optionPressed;
      styleText = styles.violetLabel;
      styleButton = styles.optionPressed;
      colorIcon = colors.primary500;
      break;
    default:
      styleButtonPressed = styles.primaryPressed;
      styleText = styles.whiteLabel;
      styleButton =
        status === strings.Button.status.disabled
          ? styles.primaryDisabled
          : styles.primary;
      colorIcon = colors.white;
      break;
  }

  return (
    <TouchableOpacity
      activeOpacity={1}
      disabled={status === "disabled" || loading}
      style={
        pressed || pressedBtn
          ? [styleButtonContainer, styleButtonPressed]
          : [styleButtonContainer, styleButton]
      }
      onPressIn={() => setPressed(true)}
      onPressOut={() => setPressed(false)}
      onPress={onPress}
      testID={testID || ""}
    >
      {!children && type === "fab" && (
        <View>
          <Icon name={icon} size={24} color={colorIcon} />
        </View>
      )}

      {children && (
        <>
          {loading && type !== "fab" && type !== "small" && (
            <View style={styles.iconContainer}>
              <ActivityIndicator size="small" color={colorIcon} />
            </View>
          )}
          {!loading && type !== "fab" && iconPosition === "left" && (
            <View
              style={
                type === "small" || type === "smallOutline" || type === "fab"
                  ? styles.iconRightSmallContainer
                  : styles.iconContainer
              }
            >
              <Icon name={icon} size={24} color={colorIcon} />
            </View>
          )}
          {type !== "small" && type !== "smallOutline" && (
            <Body
              type={
                type === "link" || type === "subLink" ? "strongLink" : "strong"
              }
              style={styleText}
            >
              {children}
            </Body>
          )}
          {type === "small" && (
            <Body type={"smStrong"} style={styleText}>
              {children}
            </Body>
          )}
          {type === "smallOutline" && (
            <Body type={"smStrong"} style={styleText}>
              {children}
            </Body>
          )}
          {!loading && (type === "fab" || iconPosition === "right") && (
            <View
              style={
                type === "small" || type === "smallOutline" || type === "fab"
                  ? styles.iconLeftSmallContainer
                  : styles.iconContainer
              }
            >
              <Icon name={icon} size={24} color={colorIcon} />
            </View>
          )}
        </>
      )}
    </TouchableOpacity>
  );
};

Button.propTypes = {
  color: PropTypes.string,
  type: PropTypes.string,
  status: PropTypes.string,
  icon: PropTypes.string,
  iconPosition: PropTypes.string,
  loading: PropTypes.bool,
  pressedBtn: PropTypes.bool,
  testID: PropTypes.string,
};

Button.defaultProps = {
  color: "default",
  type: "primary",
  status: "normal",
  icon: "home",
  loading: false,
  pressedBtn: false,
  testID: "",
};

export { Button };
