import React from "react";
import PropTypes from "prop-types";
import LinearGradient from "react-native-linear-gradient";
import { Image, TouchableHighlight } from "react-native";
import { Headline, Body } from "../typography";
import colors from "../../styles/colors";
import backgrounds from "../../styles/background";
import styles from "./index.styles";
import strings from "../../utils/strings";
import handlerType from "./actions";
import { AvatarState, images, imagesMemoji } from "./constants";
import { Icon } from "../icons";
import { HandleSvg } from "../../helpers/handleSvg";
import { availableSvg } from "../../assets/images/svg/availableSvg";

const Avatar = ({
  type,
  size,
  background,
  name,
  onPress,
  onPressIn,
  onPressOut,
  color,
  formatAvatar,
  state,
  showBorder,
  radiusZapping,
}) => {
  let format = "";
  let componentRender = "";

  switch (type) {
    case strings.Avatar.type.userInitials:
      format = formatAvatar ? formatAvatar : "circle";
      const colorFont = color ? color : colors.primaryViolet500;

      componentRender =
        size == "g" ? (
          <Headline type="h2" color={colorFont}>
            {handlerType["default"](name)}
          </Headline>
        ) : size == "m" ? (
          <Body type="smStrong" color={colorFont}>
            {handlerType["default"](name)}
          </Body>
        ) : (
          <Body type="xsStrong" color={colorFont}>
            {handlerType["default"](name)}
          </Body>
        );
      break;
    case strings.Avatar.type.userMemoji:
      format = "circle";
      const memojiSize = name + size;
      componentRender = (
        <Image source={imagesMemoji[name]} style={styles.memoji[memojiSize]} />
      );
      break;
    case strings.Avatar.type.emoji:
      format = "circle";
      componentRender = (
        <Headline
          type="h2"
          color={colors.primaryViolet500}
          style={styles.emoji[size]}
        >
          {name}
        </Headline>
      );

      break;

    case strings.Avatar.type.icon:
      format = formatAvatar ? formatAvatar : "circle";
      componentRender = (
        <Icon
          color={color ? color : colors.white}
          name={name}
          size={styles.icon[size]}
        />
      );
      break;
    case strings.Avatar.type.iconPrimary:
      format = "circle";
      componentRender = (
        <Icon color={colors.white} name={name} size={styles.icon[size]} />
      );
      break;
    case strings.Avatar.type.iconSecondary:
      format = "circle";
      componentRender = (
        <Icon color={colors.neutral900} name={name} size={styles.icon[size]} />
      );
      break;

    case strings.Avatar.type.deunaLogo:
      format = "circle";
      componentRender = (
        <HandleSvg
          type={availableSvg.DEUNA}
          color={color ? color : colors.neutral900}
          width={styles.icon[size]}
          height={styles.icon[size]}
        />
      );
      break;

    case strings.Avatar.type.bpLogo:
      format = "circle";
      componentRender = (
        <HandleSvg
          type={availableSvg.BP}
          color={color ? color : "#0F265C"}
          width={styles.icon[size]}
          height={styles.icon[size]}
        />
      );
      break;

    case strings.Avatar.type.bankLogo:
      format = "square";
      componentRender = (
        <Image
          source={images[name] || images["bankLogoDefault"]}
          style={styles.logo[size]}
        />
      );
      break;

    case strings.Avatar.type.cardLogo:
      format = "square";
      componentRender = (
        <Image
          source={images[name] || images["cardDefault"]}
          style={styles.logo[size]}
        />
      );
      break;

    case strings.Avatar.type.merchantLogo:
      format = "square";
      componentRender = (
        <Image
          source={images[name] || images["merchantDefault"]}
          style={styles.logo[size]}
        />
      );
      break;

    case strings.Avatar.type.urlLogo:
      format = formatAvatar ? formatAvatar : "square";
      componentRender = (
        <Image
          source={name}
          style={[styles.logo[size], styles.avatar[format]]}
        />
      );
      break;

    case strings.Avatar.type.zapping:
      componentRender = (
        <Image
          source={require("../../assets/images/LogoZapping.png")}
          style={{
            width: "100%",
            height: "100%",
            borderRadius: radiusZapping,
          }}
        />
      );
      break;

    default:
      format = "circle";
      break;
  }

  return (
    <TouchableHighlight
      activeOpacity={1}
      underlayColor={"transparent"}
      onPressIn={onPressIn}
      onPressOut={onPressOut}
      onPress={onPress}
    >
      <LinearGradient
        colors={
          type === strings.Avatar.type.zapping
            ? backgrounds["gradientWhite"]
            : backgrounds[background]
        }
        style={[
          styles.avatar.container,
          styles.avatar[format],
          styles.avatar[size],
          showBorder ? styles.avatar.border : undefined,
          state === AvatarState.DISABLED && styles.logoOpacity,
        ]}
      >
        {componentRender}
      </LinearGradient>
    </TouchableHighlight>
  );
};

Avatar.propTypes = {
  type: PropTypes.string,
  size: PropTypes.string,
  background: PropTypes.string,
  name: PropTypes.string,
  state: PropTypes.string,
  showBorder: PropTypes.boolean,
  radiusZapping: PropTypes.number,
};

Avatar.defaultProps = {
  type: "userInitials",
  size: "g",
  background: "gradientPurple",
  name: "De una",
  state: AvatarState.DEFAULT,
  showBorder: false,
  radiusZapping: 10,
};

export { Avatar };
