import { Image, Text, Pressable, View } from "react-native";
import PropTypes from "prop-types";
import styles from "./index.styles";
import { keyboardBase } from "./enum";
import React, { useEffect, useState } from "react";
import DeviceInfo from "react-native-device-info";
import colors from "../../styles/colors";
import { NumberComponent } from "../../atoms/typography";

const KeyboardCustomNumeric = ({
  type,
  biometricType,
  handleKey,
  hasAction,
  clear,
  maxCant,
  disable,
  initActionTouchValue,
}) => {
  const specialIconsLinks = {
    faceAuthAndroid: require("./images/keyboard/FaceAuthAndroid.png"),
    faceID: require("./images/keyboard/FaceID.png"),
    fingerPrintAndroid: require("./images/keyboard/FingerPrintAndroid.png"),
    touchID: require("./images/keyboard/TouchID.png"),
    backSpace: require("./images/keyboard/BackSpace.png"),
  };
  const [pressOutBtn, setPressOutBtn] = useState(false);
  const [movil, setMovil] = useState(false);
  const [pressed, setPressed] = useState("initial");
  const [actionTouch, setActionTouch] = useState(
    initActionTouchValue || { value: "", action: "" }
  );
  const pattern = new RegExp(
    `^([1-9]\\d{0,${maxCant ? maxCant - 1 : 8}}|0)(\\,\\d{0,2})?$`
  );

  useEffect(() => {
    const handelDetect = async () => {
      const result = await DeviceInfo.getVersion();

      setMovil(result !== "unknown" ? true : false);

      !initActionTouchValue && setActionTouch({ value: "", action: "" });
      handleKey({ value: "", action: "" });
    };
    handelDetect();
  }, []);

  useEffect(() => {
    if (clear) {
      (() => {
        setActionTouch({ value: "", action: "" });
        handleKey({ value: "", action: "" });
      })();
    }
  }, [clear]);

  const composerStyleNumber = styles.number;
  const composerStyle = styles.base;

  const handleValue = (value, action) => {
    if (disable) return;
    handleKey({ value, action });
    setActionTouch({ value, action });
  };

  const handleClick = (item) => {
    setPressOutBtn(true);
    const action = item === "fingerPrintAndroid" ? biometricType : item;

    setPressed(item);

    if (item >= 0 || item === ",") {
      if (actionTouch.value === "0" && item != ",") {
        handleValue("" + item, null);
      }

      if (actionTouch.value === "" && item === ",") {
        handleValue("0" + item, null);
      }

      if (type == "password") {
        handleValue(actionTouch.value + item, action);
      } else {
        if (pattern.test(actionTouch.value + item)) {
          handleValue(actionTouch.value + item, action);
        }
      }
    } else if (item === "backSpace") {
      handleValue(actionTouch.value.slice(0, -1), action);
    } else {
      handleValue(null, action);
    }
  };

  const verifyChangeType = (item) => {
    const result =
      item != "backSpace" && typeof item === "string" && type == "amount"
        ? ","
        : item;
    return result;
  };

  const handleSVG = (item) => {
    return item === "backSpace" ? (
      <Image
        source={specialIconsLinks[item]}
        style={{ ...styles.backSpace, ...styles.backSpaceMovil }}
      />
    ) : (
      <Image style={{ ...styles.backSpace }} source={specialIconsLinks[item]} />
    );
  };
  const handleNumberOrText = (item) => {
    return (
      <NumberComponent type={"sm"} color={colors.primaryViolet500}>
        {verifyChangeType(item)}
      </NumberComponent>
    );
  };
  const handleBackSpace = () => {
    return (
      <View style={styles.containerIcon}>
        {hasAction && (
          <>
            <Image
              source={specialIconsLinks[biometricType]}
              style={
                biometricType === "fingerPrintAndroid"
                  ? [styles.iconFinger, styles.imagesSpaceMovil]
                  : [styles.icon, styles.imagesSpaceMovil]
              }
            />
          </>
        )}
      </View>
    );
  };
  const handleImagesIcons = (item) => {
    return (
      <View style={styles.containerIcon}>
        {!movil ? (
          <Image source={specialIconsLinks[item]} style={styles.backSpace} />
        ) : (
          handleSVG(item)
        )}
      </View>
    );
  };

  return (
    <View style={composerStyle}>
      {keyboardBase.map((item, index) =>
        !hasAction && item != "backSpace" && typeof item === "string" ? (
          <View style={styles.box} key={index}>
            <Pressable
              delayPressIn={0}
              style={
                pressed == verifyChangeType(item) && pressOutBtn
                  ? [styles.circle, composerStyleNumber]
                  : [composerStyleNumber]
              }
            >
              {item >= 0 || verifyChangeType(item) === ","
                ? handleNumberOrText(item)
                : item != "backSpace"
                ? handleBackSpace()
                : handleImagesIcons(item)}
            </Pressable>
          </View>
        ) : (
          <View style={styles.box} key={index}>
            <Pressable
              delayPressIn={0}
              delayPressOut={0}
              activeOpacity={0}
              style={
                pressed == verifyChangeType(item) && pressOutBtn
                  ? [styles.circle, composerStyleNumber]
                  : [composerStyleNumber]
              }
              onPressIn={() =>
                handleClick(
                  item != "backSpace" &&
                    typeof item === "string" &&
                    type == "amount"
                    ? ","
                    : item
                )
              }
              onPressOut={() => setPressOutBtn(movil ? false : true)}
            >
              {item >= 0 || verifyChangeType(item) === ","
                ? handleNumberOrText(item)
                : item != "backSpace"
                ? handleBackSpace()
                : handleImagesIcons(item)}
            </Pressable>
          </View>
        )
      )}
    </View>
  );
};

KeyboardCustomNumeric.propTypes = {
  type: PropTypes.string,
  biometricType: PropTypes.string,
  handleKey: PropTypes.func.isRequired,
  hasAction: PropTypes.bool,
  clear: PropTypes.bool,
  disable: PropTypes.bool,
};

KeyboardCustomNumeric.defaultProps = {
  type: "password",
  biometricType: "fingerPrintAndroid",
  hasAction: false,
  clear: false,
  disable: false,
};

export { KeyboardCustomNumeric };
