import { availableSvg } from "../assets/images/svg/availableSvg";

/**
 * Render Svg in app why this is a error
 * @param {*} type
 * @returns Svg
 */
export const HandleSvg = ({ type, width, height, color, marginTop }) => {
  try {
    let Logo;
    if (type === availableSvg.BP)
      Logo = require("../assets/images/svg/icn-BP.svg").default;
    if (type === availableSvg.DEUNA)
      Logo = require("../assets/images/svg/icn-deuna.svg").default;
    if (Logo) {
      return (
        <Logo
          width={width}
          height={height}
          fill={color}
          marginTop={marginTop}
        />
      );
    }
  } catch (error) {
    return <></>;
  }
};
