import React, { useState } from "react";
import { TouchableHighlight, View, Image } from "react-native";
import strings from "../../utils/strings";
import styles from "./index.styles";
import { Avatar } from "../../atoms/avatar";
import { Body, NumberComponent } from "../../atoms/typography";
import { Button } from "../button";
import colors from "../../styles/colors";
import { Icon } from "../../atoms/icons";
import { ToogleSwitch } from "../forms/toogleSwitch";
import PropTypes from "prop-types";
import { ItemState } from "./constant";

const Item = ({
  children,
  type,
  nameAvatar,
  typeAvatar,
  iconName,
  iconColor,
  title,
  uri,
  subtitle,
  subtitleColor,
  bottomSubtitle,
  bottomSubtitleColor,
  isButtonPressed,
  onPress,
  onPressButton,
  pressedItem,
  disabledAnimation,
  formatAvatar,
  background,
  color,
  amount,
  amountPost,
  showIcon,
  visibleAmount,
  hideSensitiveViews,
  state,
  isSelected,
  label,
  opacity,
  menuTrigger,
  isPending,
  ...props
}) => {
  const [pressed, setPressed] = useState(false);
  let underlayColor = colors.neutralVariant50;
  let underlayColorDisabled = colors.neutralVariant50;
  const elipsisCount = 5;
  const hiddenAmount = () => {
    return (
      <View
        style={styles.ellipsesContainer}
        testID="item-hidden-amount-container"
      >
        {new Array(elipsisCount).fill(0).map((_, index) => (
          <View
            style={[
              styles.ellipse,
              { marginRight: index !== elipsisCount - 1 ? 4 : 0 },
            ]}
            key={`ellipse-${index}`}
          />
        ))}
      </View>
    );
  };
  let componentRender;

  const elementItemStyleAvatar = {
    ...styles.itemAvatar,
    ...(props.paddingVerticalAvatar && {
      paddingVertical: props.paddingVerticalAvatar,
    }),
  };

  const elementStyleContent = {
    ...styles.itemContent,
    ...(props.paddingVerticalContent && {
      paddingVertical: props.paddingVerticalContent,
    }),
  };

  const AvatarDefault = () => (
    <View style={styles.itemAvatar}>
      <Avatar
        type={typeAvatar}
        background={background}
        size="m"
        name={nameAvatar}
        color={color}
        formatAvatar={formatAvatar}
      />
    </View>
  );

  const AvatarContentDefault = () => (
    <View style={styles.itemContent}>
      <Body style={styles.itemTextTitle} type="smStrong">
        {title}
      </Body>
      {subtitle && (
        <Body type={"sm"} style={styles.itemTextSubtitle}>
          {subtitle}
        </Body>
      )}
    </View>
  );

  const AvatarContentWithAnotherContainers = () => (
    <View style={styles.itemContent}>
      <View style={styles.itemTitle}>
        <Body style={styles.itemTextTitle} type="smStrong">
          {title}
        </Body>
        {label && (
          <View style={styles.itemLabel}>
            <Body style={styles.itemTextLabel} type="xs">
              {label}
            </Body>
          </View>
        )}
      </View>
      {subtitle && (
        <Body type={"sm"} style={styles.itemTextSubtitle}>
          {subtitle}
        </Body>
      )}
    </View>
  );

  const AvatarContentDefaultWithoutSubtitleValidation = () => (
    <View style={[styles.itemContent, { paddingRight: 16 }]}>
      <Body style={styles.itemTextTitle} type="smStrong">
        {title}
      </Body>
      <Body type={"sm"} style={styles.itemTextSubtitle}>
        {subtitle}
      </Body>
    </View>
  );

  const ValidationIcons = () => {
    if (isSelected) {
      return (
        <View style={[styles.itemButton]}>
          <Icon color={colors.black} name={"check"} size={24} />
        </View>
      );
    }

    if (showIcon) {
      return (
        <View style={[styles.itemButton]}>
          <Icon color={colors.black} name={"chevron-right"} size={24} />
        </View>
      );
    }

    return null;
  };

  switch (type) {
    case strings.Item.type.header:
      underlayColor = "transparent";

      componentRender = (
        <View style={styles.itemHeaderContainer}>
          <View style={styles.itemHeaderLogo}>
            <Avatar
              background={background}
              color={color}
              type={typeAvatar ? typeAvatar : "userInitials"}
              size="g"
              name={nameAvatar}
            />
          </View>
          <View style={styles.itemHeaderContent}>
            <Body
              style={[
                styles.itemTextTitle,
                {
                  textAlign: props.align,
                },
              ]}
              type="smStrong"
            >
              {title}
            </Body>
            <Body style={styles.itemHeaderSubtitle} type="sm">
              {subtitle}
            </Body>
          </View>
        </View>
      );
      break;

    case strings.Item.type.contact:
      componentRender = (
        <View style={[styles.item, { opacity: opacity }]}>
          <AvatarDefault />
          <AvatarContentDefault />
          {showIcon && iconName !== "" && (
            <View style={[styles.itemButton]}>
              <Icon color={colors.black} name={iconName} size={24} />
            </View>
          )}
        </View>
      );

      break;

    case strings.Item.type.invite:
      componentRender = (
        <View style={styles.item}>
          <AvatarDefault />
          <AvatarContentDefault />
          {showIcon && (
            <View style={styles.itemButton}>
              <Button
                iconPosition="default"
                type="small"
                onPress={onPressButton}
              >
                Invitar
              </Button>
            </View>
          )}
        </View>
      );

      break;

    case strings.Item.type.product:
      componentRender = (
        <View style={styles.item}>
          {nameAvatar && (
            <View style={styles.itemAvatar}>
              <Avatar
                state={state}
                type="cardLogo"
                size="m"
                name={nameAvatar}
              />
            </View>
          )}
          <View style={styles.itemContent}>
            <Body
              color={
                state === ItemState.DISABLED
                  ? colors.neutralVariant700
                  : colors.neutral700
              }
              type="smStrong"
            >
              {title}
            </Body>
            <View style={styles.itemSubtitleContent}>
              {subtitle && (
                <Body
                  type={"sm"}
                  style={{ width: "60%" }}
                  color={colors.neutralVariant700}
                >
                  {subtitle}
                </Body>
              )}
              {amount && (
                <Body
                  type={"sm"}
                  style={{ width: "35%" }}
                  color={colors.neutralVariant700}
                >
                  {amount}
                </Body>
              )}
            </View>
          </View>
          <ValidationIcons />
        </View>
      );
      break;

    case strings.Item.type.primary:
      componentRender = (
        <View style={styles.item}>
          <View style={styles.itemAvatar}>
            <Avatar
              type={typeAvatar || "iconPrimary"}
              background="gradientPrimary"
              size="m"
              name={nameAvatar}
              formatAvatar={formatAvatar}
              color={color}
            />
          </View>
          <AvatarContentWithAnotherContainers />
          {showIcon && (
            <View style={[styles.itemButton]}>
              <Icon color={colors.black} name={"chevron-right"} size={24} />
            </View>
          )}
        </View>
      );
      break;

    case strings.Item.type.primaryLight:
      componentRender = (
        <View style={[styles.item, { opacity: opacity }]}>
          <View style={elementItemStyleAvatar}>
            <Avatar
              type={typeAvatar || "iconSecondary"}
              background={background || "gradientWhite"}
              size="m"
              name={nameAvatar}
              formatAvatar={formatAvatar}
              color={color}
              showBorder
            />
          </View>
          <AvatarContentWithAnotherContainers />
          {showIcon && (
            <View style={[styles.itemButton]}>
              <Icon color={colors.black} name={"chevron-right"} size={24} />
            </View>
          )}
        </View>
      );
      break;

    case strings.Item.type.secondary:
      componentRender = (
        <View style={styles.item}>
          <View style={styles.itemAvatar}>
            <Avatar
              type={typeAvatar || "iconSecondary"}
              background={
                pressed || pressedItem ? "gradientWhite" : "gradientSecondary"
              }
              size="m"
              name={nameAvatar}
              formatAvatar={formatAvatar}
              color={color}
            />
          </View>
          <AvatarContentWithAnotherContainers />
        </View>
      );
      break;

    case strings.Item.type.confirm:
      componentRender = (
        <View style={styles.item}>
          <View style={styles.itemAvatar}>
            <Avatar
              type={typeAvatar}
              background={background}
              size="m"
              name={nameAvatar}
              color={color}
            />
          </View>
          <View
            style={[
              styles.itemContent,
              { paddingVertical: 5, opacity: opacity },
            ]}
          >
            <Body style={styles.itemTextTitle} type="xs">
              {title}
            </Body>
            <Body type={"smStrong"} style={{ marginTop: 4 }}>
              {subtitle}
            </Body>
            {children && <Body type={"smStrong"}>{children}</Body>}
          </View>
          {showIcon && (
            <View style={[styles.itemButton]}>
              <Icon color={colors.black} name={"chevron-right"} size={24} />
            </View>
          )}
        </View>
      );
      break;

    case strings.Item.type.option:
      underlayColor = colors.neutralVariant100;

      componentRender = (
        <View style={[styles.item, { opacity: opacity }]}>
          <View style={elementItemStyleAvatar}>
            <Avatar
              type={typeAvatar}
              background={background}
              size={props.size || "m"}
              name={nameAvatar}
              color={color}
              formatAvatar={formatAvatar}
            />
          </View>
          <View style={elementStyleContent}>
            <Body style={styles.itemTextTitle} type="smStrong">
              {title}
            </Body>
            <View style={styles.itemSubtitleContent}>
              {subtitle && (
                <Body
                  type={"xs"}
                  style={{ width: "70%" }}
                  color={colors.neutralVariant700}
                >
                  {subtitle}
                </Body>
              )}
              {amount && (
                <Body
                  style={{ marginRight: -10 }}
                  type={"xs"}
                  color={colors.neutralVariant700}
                >
                  {amount}
                </Body>
              )}
            </View>
          </View>
          <ValidationIcons />
        </View>
      );
      break;

    case strings.Item.type.toggle:
      componentRender = (
        <View
          style={[
            styles.itemCard,
            { paddingHorizontal: 16, paddingVertical: 24 },
          ]}
        >
          <View>
            <Avatar type="iconPrimary" size="m" name={"plus"} />
          </View>
          <View style={{ flex: 1, paddingLeft: 16 }}>
            <Body style={styles.itemTextTitle} type="smStrong">
              {title}
            </Body>
            <Body type={"sm"} style={{ marginTop: 8 }}>
              {subtitle}
            </Body>
          </View>
          <View>
            <ToogleSwitch getSwitchValue={onPressButton} />
          </View>
        </View>
      );
      break;

    case strings.Item.type.info:
      componentRender = (
        <View style={styles.item}>
          <View style={styles.itemAvatar}>
            <Avatar
              type={typeAvatar ? typeAvatar : "userInitials"}
              size="m"
              name={nameAvatar}
            />
          </View>
          <AvatarContentDefaultWithoutSubtitleValidation />
        </View>
      );
      break;

    case strings.Item.type.image:
      componentRender = (
        <View style={styles.item}>
          <View style={styles.itemAvatar}>
            <Image source={{ uri }} style={styles.itemImage} />
          </View>
          <AvatarContentDefaultWithoutSubtitleValidation />
        </View>
      );
      break;

    case strings.Item.type.feature:
      underlayColor = "transparent";
      componentRender = (
        <View style={{ flexDirection: "row" }}>
          <View style={{ paddingBottom: 10 }}>
            <Avatar
              type="icon"
              size="m"
              name={nameAvatar}
              background="gradientBlack"
            />
          </View>
          <View style={styles.itemContentFeature}>
            <Body style={styles.itemTextTitle} type="smStrong">
              {title}
            </Body>
            <Body type={"sm"} style={{ marginTop: 4 }}>
              {subtitle}
            </Body>
          </View>
        </View>
      );
      break;

    case strings.Item.type.card:
      componentRender = (
        <View style={styles.itemCard}>
          <View style={styles.itemAvatarCard}>
            <Avatar
              type="iconPrimary"
              size="m"
              name={nameAvatar}
              background={background}
            />
          </View>
          <View style={styles.itemContentCard}>
            <Body style={styles.itemTextTitle} type="smStrong">
              {title}
            </Body>
            <Body type={"sm"} style={{ marginTop: 4, paddingRight: 16 }}>
              {subtitle}
            </Body>
            {children && (
              <Body
                type={"smLink"}
                style={{ marginTop: 4 }}
                color={colors.primaryViolet500}
              >
                {children}
              </Body>
            )}
          </View>
        </View>
      );
      break;

    case strings.Item.type.shortcut:
      underlayColor = "transparent";
      componentRender = (
        <View
          style={[
            styles.itemShortcutContainer,
            {
              backgroundColor: background ? background : colors.primary500,
            },
          ]}
        >
          <Icon
            color={color ? color : colors.white}
            name={iconName}
            size={26}
            style={styles.itemShortcutIcon}
          />
          <Body
            color={color ? color : colors.white}
            type={"xsStrong"}
            style={styles.itemShortcutTitle}
          ></Body>
        </View>
      );
      break;

    case strings.Item.type.smallContact:
      underlayColor = "transparent";
      componentRender = (
        <View style={styles.itemSmallContainer}>
          <View style={styles.itemSmallLogo}>
            <View
              style={
                pressed || pressedItem
                  ? styles.itemSmallBorder
                  : styles.itemSmallNoBorder
              }
            >
              <Avatar type="userInitials" size="m" name={nameAvatar} />
            </View>
          </View>
          <Body type="smStrong" style={styles.itemSmallTitle} numberOfLines={2}>
            {title}
          </Body>
        </View>
      );
      break;

    case strings.Item.type.smallReason:
      underlayColor = "transparent";
      componentRender = (
        <View style={styles.itemSmallContainer}>
          <View style={styles.itemSmallLogo}>
            <View
              style={
                pressed || pressedItem
                  ? styles.itemSmallBorder
                  : styles.itemSmallNoBorder
              }
            >
              <Avatar type="emoji" size="m" name={nameAvatar} />
            </View>
          </View>
          <Body type="xsStrong" style={styles.itemSmallTitle} numberOfLines={2}>
            {title}
          </Body>
        </View>
      );
      break;

    case strings.Item.type.smallProduct:
      underlayColor = "transparent";
      componentRender = (
        <View style={styles.itemProductContainer}>
          <View style={styles.itemProductLogo}>
            <Avatar type="cardLogo" size="m" name={nameAvatar} />
          </View>
          <Body
            type="xsStrong"
            style={styles.itemProductTitle}
            numberOfLines={2}
          >
            {title}
          </Body>
        </View>
      );
      break;

    case strings.Item.type.smallPerfil:
      underlayColor = "transparent";
      componentRender = (
        <View
          style={[
            styles.itemPerfilContainer,
            {
              borderColor: pressedItem
                ? colors.darkGray300
                : colors.primaryViolet500,
            },
          ]}
        >
          <View style={styles.itemPerfilLogo}>
            <Avatar
              type="emoji"
              size="s"
              name={nameAvatar}
              background="gradientTransparent"
            />
          </View>
          <View style={styles.itemPerfilTitle}>
            <Body
              type={"xsStrong"}
              color={pressedItem ? colors.neutral900 : colors.primaryViolet500}
            >
              {title}
            </Body>
          </View>
        </View>
      );
      break;

    case strings.Item.type.movement:
      underlayColor = "transparent";
      const pendingIcon = require("../../assets/images/pending-container.png");
      componentRender = (
        <View style={styles.item}>
          <View style={[styles.itemAvatar, { paddingLeft: 0 }]}>
            <Avatar
              type={typeAvatar}
              background={background}
              size="m"
              name={nameAvatar}
              color={color}
              formatAvatar={formatAvatar}
            />
            {isPending ? (
              <Image
                source={pendingIcon}
                style={styles.pendingContainerImage}
              />
            ) : null}
          </View>
          <View style={styles.itemContent}>
            <Body
              style={styles.itemContentTitle}
              color={colors.neutral700}
              type="smStrong"
            >
              {title}
            </Body>
            <View>
              <Body
                style={styles.itemTextSubtitleMovement}
                color={colors.neutralVariant700}
                type="sm"
              >
                {subtitle}
              </Body>
              {bottomSubtitle ? (
                <Body
                  style={styles.itemTextSubtitleMovement}
                  color={bottomSubtitleColor || colors.neutralVariant700}
                  type="sm"
                >
                  {bottomSubtitle}
                </Body>
              ) : null}
            </View>
          </View>
          <View
            style={{
              justifyContent: "center",
              alignItems: "flex-end",
            }}
          >
            <NumberComponent
              color={
                amount.charAt(0) == "+" ? colors.success500 : colors.neutral900
              }
              type={"xs"}
            >
              {amount}
            </NumberComponent>
            {isPending ? (
              <Body
                style={styles.itemTextSubtitleMovement}
                color={colors.warning700}
                type="sm"
              >
                Pendiente
              </Body>
            ) : null}
            {amountPost && (
              <Body
                color={colors.neutralVariant700}
                style={styles.cantDown}
                type="sm"
              >
                {visibleAmount ? amountPost : hiddenAmount()}
              </Body>
            )}
          </View>
        </View>
      );
      break;

    case strings.Item.type.copy:
      componentRender = (
        <View style={styles.itemContainer}>
          <View style={styles.textContainer}>
            <Body type={"sm"} color={colors.neutralVariant700}>
              {title}
            </Body>
            <Body style={{ marginTop: 2 }} type="smStrong" color={colors.black}>
              {subtitle}
            </Body>
          </View>
          {showIcon && (
            <View style={styles.iconContainer}>
              <Icon
                color={colors.black}
                name={iconName}
                size={20}
                style={styles.itemIcon}
              />
            </View>
          )}
        </View>
      );
      break;

    case strings.Item.type.limit:
      componentRender = (
        <View style={styles.itemContainer}>
          <View style={styles.textContainer}>
            <Body type={"smStrong"} color={colors.neutral700}>
              {title}
            </Body>
            <NumberComponent
              style={{ marginTop: 2 }}
              type="xs"
              color={colors.neutralVariant700}
            >
              {subtitle}
            </NumberComponent>
          </View>
          {showIcon && (
            <View style={styles.iconContainer}>
              <Icon
                color={colors.black}
                name={iconName}
                size={20}
                style={styles.itemIcon}
              />
            </View>
          )}
        </View>
      );
      break;

    case strings.Item.type.elementAccount:
      componentRender = (
        <View style={[styles.item, styles.itemElementAccount]}>
          <View style={[styles.itemAvatar, { opacity: opacity }]}>
            <Avatar
              type={typeAvatar}
              background={background}
              size="m"
              name={nameAvatar}
              color={color}
              formatAvatar={formatAvatar}
            />
          </View>
          <View style={[styles.itemContent, { opacity: opacity }]}>
            <Body style={styles.itemTextTitle} type="smStrong">
              {title}
            </Body>
            {subtitle && (
              <Body type={"sm"} style={styles.itemTextSubtitle}>
                {subtitle}
              </Body>
            )}
          </View>
          {Boolean(menuTrigger) ? menuTrigger : null}
        </View>
      );
      break;

    case strings.Item.type.elementItem:
      componentRender = (
        <View style={styles.item}>
          <View style={elementItemStyleAvatar}>
            <Avatar
              type={typeAvatar}
              background={background}
              size={props.size || "m"}
              name={nameAvatar}
              color={color}
              formatAvatar={formatAvatar}
            />
          </View>
          <View style={elementStyleContent}>
            <Body style={styles.itemTextTitle} type="smStrong">
              {title}
            </Body>
            {subtitle && (
              <Body
                type={"sm"}
                style={{
                  color: subtitleColor,
                }}
              >
                {subtitle}
              </Body>
            )}
          </View>
          {showIcon && (
            <View style={[styles.itemButton]}>
              <Icon
                color={iconColor}
                name={iconName || "chevron-right"}
                size={24}
              />
            </View>
          )}
        </View>
      );
      break;

    default:
      componentRender = "";
      underlayColor = "transparent";
      break;
  }

  return (
    <TouchableHighlight
      ref={(container) => {
        if (hideSensitiveViews) hideSensitiveViews(container);
      }}
      disabled={state === ItemState.DISABLED}
      activeOpacity={1}
      onPressIn={() => setPressed(true)}
      onPressOut={() => setPressed(false)}
      onPress={onPress}
      style={[
        type == "smallContact" ||
        type == "smallReason" ||
        type == "smallProduct" ||
        type == "smallPerfil"
          ? {}
          : styles.itemLarge,
        type == "option" ||
        type == "optionCheck" ||
        type == "info" ||
        type === "image"
          ? styles.itemWithBackground
          : {},
        pressedItem && { backgroundColor: underlayColor },
      ]}
      underlayColor={
        disabledAnimation
          ? type == "option" ||
            type == "optionCheck" ||
            type == "info" ||
            type === "image"
            ? underlayColorDisabled
            : "transparent"
          : underlayColor
      }
      {...props}
    >
      {componentRender}
    </TouchableHighlight>
  );
};

Item.propTypes = {
  type: PropTypes.string,
  nameAvatar: PropTypes.string,
  typeAvatar: PropTypes.string,
  iconName: PropTypes.string,
  iconColor: PropTypes.string,
  title: PropTypes.string,
  subtitle: PropTypes.string,
  subtitleColor: PropTypes.string,
  bottomSubtitle: PropTypes.string,
  bottomSubtitleColor: PropTypes.string,
  onPress: PropTypes.func,
  onPressButton: PropTypes.func,
  pressedItem: PropTypes.bool,
  isButtonPressed: PropTypes.bool,
  disabledAnimation: PropTypes.bool,
  formatAvatar: PropTypes.string,
  background: PropTypes.string,
  color: PropTypes.string,
  amount: PropTypes.string,
  amountPost: PropTypes.string,
  showIcon: PropTypes.bool,
  visibleAmount: PropTypes.bool,
  hideSensitiveViews: PropTypes.func,
  isSelected: PropTypes.bool,
  label: PropTypes.string,
  opacity: PropTypes.number,
  uri: PropTypes.string,
};
Item.defaultProps = {
  type: "primary",
  showIcon: true,
  pressedItem: false,
  disabledAnimation: false,
  isButtonPressed: false,
  state: ItemState.DEFAULT,
  opacity: 1,
  iconName: "",
  iconColor: colors.black,
  subtitleColor: colors.neutralVariant700,
};

export { Item };
