import React from "react";
import PropTypes from "prop-types";
import { useThemeContext } from "../../../theming/themeProvider";
import { NumberStylesComponent } from "./index.styles";
import colors from "../../../styles/colors";

const NumberComponent = ({ style, children, weight, ...props }) => {
  const theme = useThemeContext();
  return (
    <NumberStylesComponent theme={theme} style={style} {...props}>
      {children}
    </NumberStylesComponent>
  );
};

NumberComponent.propTypes = {
  type: PropTypes.oneOfType([PropTypes.string]),
  color: PropTypes.oneOfType([PropTypes.string]),
};

NumberComponent.defaultProps = {
  type: "md",
  color: colors.neutral700,
};

export { NumberComponent };
