import { emojiList, icons } from "./enum";
const handlerType = {
  default: (name) => formatTextAvatar(name),
  emoji: (name, custon) => formatUrlEmojiAvatar(name, custon),
  icon: (name, url) => formatUrlIconAvatar(name, url),
};

const formatTextAvatar = (name) => {
  const result = name
    ? name
        .replace(/[^\p{L}\s]/gu, "")
        .split(/\s+/)
        .map((word) => word[0])
        .join("")
        .slice(0, 2)
        .toUpperCase()
    : "";
  return result;
};

const formatUrlEmojiAvatar = (name, custon) => {
  return custon ? custon : emojiList[name] ? emojiList[name] : emojiList.louch;
};
const formatUrlIconAvatar = (name, custom) => {
  return custom ? custom : icons[name] ? icons[name] : icons.primary;
};

export default handlerType;
