import React, { useState, useEffect } from "react";
import {
  View,
  TextInput,
  Text,
  ActivityIndicator,
  TouchableHighlight,
  TouchableOpacity,
} from "react-native";

import PropTypes from "prop-types";
import { useThemeContext } from "../../../theming/themeProvider";
import { styles, placeHolderStyle } from "./input.styles";

import { Body } from "../../../atoms/typography";
import colors from "../../../styles/colors";

import { InputState, InputType } from "./constants";
import { Icon } from "../../../atoms/icons";

export { InputState, InputType } from "./constants";

import { Avatar } from "../../../atoms/avatar";

const FormInput = ({
  type,
  value,
  placeholder,
  onChangeText,
  onInputFocus,
  onInputBlur,
  label,
  state,
  style,
  microcopy,
  validationText,
  icon,
  iconColor,
  maxLength,
  isLoading,
  isValidated,
  keyboardType,
  onSubmitEditing,
  focus,
  background,
  iconOnPress,
  regex,
  colorText,
  prefixValue,
  highlightMicrocopy,
  preAvatarProps,
  textStyleProps,
  buttonColor,
  buttonText,
  buttonAction,
  ...props
}) => {
  const theme = useThemeContext();
  const [currentValue, setCurrentValue] = useState("");
  const [currentKeyboardType, setCurrentKeyboardType] = useState(
    keyboardType || "default"
  );
  const [currentType, setCurrentType] = useState(type || InputType.TEXT);
  const [currentState, setCurrentState] = useState(InputState.DEFAULT);
  const [textLength, setTextLength] = useState(0);
  const [currentMaxLength, setCurrentMaxLength] = useState(0);
  const [isEditable, setIsEditable] = useState(true);
  const [inputStyles, setInputStyles] = useState({});
  const [isChangeValue, setIsChangeValue] = useState(false);

  useEffect(() => {
    if (type) {
      setCurrentType(type);
    }
    if (value) {
      setCurrentValue(value);
    }
    if (state) {
      setCurrentState(state);
    }
    if (maxLength) {
      setCurrentMaxLength(maxLength);
    }
    if (keyboardType) {
      setCurrentKeyboardType(keyboardType);
    }
  }, []);

  useEffect(() => {
    onInputChange(value);
  }, [value]);

  useEffect(() => {
    if (type) {
      setCurrentType(type);
    }
  }, [type]);

  useEffect(() => {
    if (maxLength) {
      setCurrentMaxLength(maxLength);
    }
  }, [maxLength]);

  useEffect(() => {
    if (state) {
      setIsEditable(true);
      if (state === InputState.DISABLED) {
        setIsEditable(false);
      }
      if (state === InputState.ERROR) {
        setIsChangeValue(false);
      }
      setCurrentState(state);
      getInputStyles(state);
    }
  }, [state]);

  const truncateDecimals = (input) => {
    let newInput = input.replace(".", ",");

    const parts = newInput.split(",");
    if (parts.length >= 2) {
      const integerPart = parts[0];
      const decimalPart = parts[1].slice(0, 2);
      newInput = integerPart + "," + decimalPart;
    }
    return newInput;
  };

  const getInputStyles = (state) => {
    setInputStyles({
      ...theme.input.style,
      ...theme.input.state[state],
    });
  };

  const onInputChange = (inputText) => {
    setIsChangeValue(currentValue !== inputText);
    setFilled(inputText);
    let text = inputText;

    if (type === "amount") {
      text = truncateDecimals(text);
    }

    setCurrentValue(text);
    if (onChangeText !== undefined) {
      onChangeText(text);
    }
    setTextLength(inputText.length);
  };

  const onInputKeyPress = (event) => {
    const { key, keyCode } = event.nativeEvent;

    if (key === "Backspace" || key === "Enter" || key === "Delete") return true;
    if (key === "." || key === ",") return true;
    if (keyCode === 32) {
      return true;
    }

    if (keyCode >= 48 && keyCode <= 57) {
      return true;
    }

    if (keyCode >= 65 && keyCode <= 90) {
      return true;
    }
    event.stopPropagation();
    event.preventDefault();
  };

  const onFocus = (e) => {
    if (currentState === InputState.ERROR && !isChangeValue) return;
    if (currentState === InputState.DISABLED) {
      getInputStyles(InputState.DISABLED);
    } else {
      setCurrentState(InputState.FOCUS);
      getInputStyles(InputState.FOCUS);
    }
    if (onInputFocus !== undefined) {
      onInputFocus(e);
    }
    setIsChangeValue(false);
  };

  const onBlur = (e) => {
    if (currentState === InputState.ERROR && !isChangeValue) return;
    if (currentState && currentState.length > 0) {
      setCurrentState(
        state === "error" ? InputState.ERROR : InputState.DEFAULT
      );
      getInputStyles(state === "error" ? InputState.ERROR : InputState.DEFAULT);
    }
    if (onInputBlur !== undefined) {
      onInputBlur(e);
    }
    setIsChangeValue(false);
  };

  const setFilled = (value) => {
    if (value && value.length > 0) {
      setCurrentState(state === "error" ? InputState.ERROR : InputState.FOCUS);
      getInputStyles(state === "error" ? InputState.ERROR : InputState.FOCUS);
    }
  };

  const renderLabel = () => {
    const hasLabel = label !== undefined && label.length > 0;
    return (
      hasLabel && (
        <View style={styles.LabelContainer}>
          <Body type={"xsStrong"} style={{ color: colors.neutralVariant700 }}>
            {label}
          </Body>
        </View>
      )
    );
  };

  const renderMicrocopy = () => {
    const hasMicrocopy = microcopy !== undefined && microcopy.length > 0;
    return (
      hasMicrocopy && (
        <View style={styles.descriptionSection}>
          <Body
            type={highlightMicrocopy ? "xsStrong" : "xs"}
            numberOfLines={2}
            style={
              highlightMicrocopy
                ? styles.microcopyHighlighted
                : styles.microcopy
            }
          >
            {microcopy}
          </Body>
        </View>
      )
    );
  };

  const renderValidationText = () => {
    const showErrorText = currentState === InputState.ERROR;
    return (
      showErrorText && (
        <View style={styles.descriptionSection}>
          <Body
            type={"smStrong"}
            numberOfLines={2}
            style={styles.validationText}
          >
            {validationText}
          </Body>
        </View>
      )
    );
  };

  const renderPreAvatar = () => {
    if (preAvatarProps) {
      return (
        <View style={styles.preAvatarStyle}>
          <Avatar
            type={preAvatarProps.typeAvatar}
            size={preAvatarProps.sizePreAvatar}
            name={preAvatarProps.preAvatar}
          />
        </View>
      );
    }
  };

  const renderIconAmount = () => {
    if (icon && icon !== "") {
      return (
        <TouchableHighlight
          activeOpacity={1}
          underlayColor={"transparent"}
          onPress={iconOnPress}
          style={styles.searchIcon}
        >
          <View>
            <Icon
              size={24}
              name={icon}
              color={iconColor ? colors[iconColor] : colors.neutral700}
            />
          </View>
        </TouchableHighlight>
      );
    }
  };

  renderButton = () => {
    if (buttonColor && buttonText) {
      return (
        <View style={styles.searchIcon}>
          <TouchableOpacity
            onPress={buttonAction}
            style={[styles.buttonStyle, { backgroundColor: buttonColor }]}
          >
            <Text style={styles.textButton}>{buttonText}</Text>
          </TouchableOpacity>
        </View>
      );
    }
  };

  const renderIcon = () => {
    if (isValidated && currentState !== InputState.ERROR) {
      return (
        <View style={styles.searchIcon}>
          <Icon size={24} color={colors.success500} name={"check-circle"} />
        </View>
      );
    } else if (isLoading && currentState !== InputState.ERROR) {
      return (
        <View style={styles.searchIcon}>
          <ActivityIndicator color={colors.primary500} size={24} />
        </View>
      );
    }

    if (currentType === InputType.PREFIX || currentType === InputType.AMOUNT) {
      return (
        <View style={styles.prefixStyle}>
          <Body>{prefixValue}</Body>
        </View>
      );
    }

    if (currentType === InputType.SUFIX) {
      if (currentState === InputState.ERROR) {
        return (
          <View style={styles.searchIcon}>
            <Body color={colors.error500}>
              {textLength}/{currentMaxLength}
            </Body>
          </View>
        );
      } else {
        return (
          <View style={styles.searchIcon}>
            <Body>
              {textLength}/{currentMaxLength}
            </Body>
          </View>
        );
      }
    }

    if (currentType === InputType.TEXT) {
      if (icon) {
        return (
          <TouchableHighlight
            activeOpacity={1}
            underlayColor={"transparent"}
            onPress={iconOnPress}
            style={styles.searchIcon}
          >
            <View>
              <Icon
                size={24}
                name={icon}
                color={iconColor ? colors[iconColor] : colors.neutral700}
              />
            </View>
          </TouchableHighlight>
        );
      }
    }

    if (currentType === InputType.SEARCH) {
      return (
        <TouchableHighlight
          activeOpacity={1}
          underlayColor={"transparent"}
          onPress={() => {
            currentValue.length > 0 && clearSearchInput();
          }}
          style={styles.searchIcon}
        >
          <View>
            <Icon
              size={24}
              name={currentValue.length > 0 ? "close-circle" : "magnify"}
            />
          </View>
        </TouchableHighlight>
      );
    }
  };

  const clearSearchInput = () => {
    setCurrentValue("");
    onInputChange("");
  };

  return (
    <View
      testID={props.testID || "form-input-container-default-test-id"}
      key={props.testID || "form-input-container-default-test-id"}
      name={props.testID || "form-input-container-default-test-id"}
    >
      {renderLabel()}
      <View style={[{ ...style }, styles.container]}>
        <View
          style={[
            styles.searchSection,
            inputStyles,
            { backgroundColor: colors[background] },
          ]}
        >
          {(type === InputType.PREFIX || type === InputType.AMOUNT) &&
            renderIcon()}
          {preAvatarProps && renderPreAvatar()}
          <TextInput
            autoFocus={focus}
            value={currentValue}
            placeholder={placeholder}
            onChangeText={(value) =>
              regex
                ? onInputChange(value.replace(regex, ""))
                : onInputChange(value)
            }
            onKeyPress={onInputKeyPress}
            onFocus={onFocus}
            style={[
              type === InputType.PREFIX || type === InputType.AMOUNT
                ? [styles.prefixTextInput, textStyleProps]
                : [
                    styles.textInput,
                    { color: colorText ?? colors.neutralVariant700 },
                    textStyleProps,
                  ],
            ]}
            onBlur={onBlur}
            placeholderTextColor={placeHolderStyle}
            keyboardType={currentKeyboardType}
            maxLength={currentMaxLength}
            editable={isEditable}
            selectTextOnFocus={isEditable}
            onSubmitEditing={onSubmitEditing}
            testID={props.testID ? props.testID : "form-input-default-test-id"}
            {...props}
          />
          {buttonColor && buttonText && renderButton()}
          {!(type === InputType.PREFIX || type === InputType.AMOUNT) &&
            renderIcon()}
          {type === InputType.AMOUNT && renderIconAmount()}
        </View>
      </View>
      {renderValidationText()}
      {renderMicrocopy()}
    </View>
  );
};

FormInput.propTypes = {
  type: PropTypes.string,
  placeholder: PropTypes.string,
  value: PropTypes.string,
  label: PropTypes.string,
  microcopy: PropTypes.string,
  highlightMicrocopy: PropTypes.bool,
  validationText: PropTypes.string,
  state: PropTypes.string,
  icon: PropTypes.string,
  maxLength: PropTypes.number,
  isLoading: PropTypes.bool,
  isValidated: PropTypes.bool,
  background: PropTypes.string,
  iconOnPress: PropTypes.func,
  prefixValue: PropTypes.string,
  buttonColor: PropTypes.string,
  buttonText: PropTypes.string,
  buttonAction: PropTypes.func,
};

FormInput.defaultProps = {
  type: "text",
  placeholder: "",
  value: "",
  label: "",
  microcopy: "",
  highlightMicrocopy: false,
  validationText: "",
  state: InputState.DEFAULT,
  icon: "",
  iconColor: undefined,
  maxLength: 100,
  isLoading: false,
  isValidated: false,
  background: "transparent",
  prefixValue: "$",
  preAvatarProps: undefined,
  textStyleProps: undefined,
  buttonColor: undefined,
  buttonText: undefined,
  buttonAction: undefined,
};

export { FormInput };
