import React, { useEffect, useState } from "react";
import { View, TouchableOpacity, Animated, Easing, Text } from "react-native";

import PropTypes from "prop-types";
import { styles } from "./index.styles";

const ToogleSwitch = ({ value, disabled, onPress = null }) => {
  const animatedValue = React.useRef(new Animated.Value(0)).current;
  const [status, setStatus] = useState(value);
  animatedValue.setValue(status ? 1 : 0);

  const toggleSwitch = () => {
    Animated.timing(animatedValue, {
      toValue: status ? 0 : 1,
      duration: 200,
      easing: Easing.linear,
      useNativeDriver: false,
    }).start();
    setStatus(!status);
    if (onPress) {
      onPress(!status);
    }
  };

  const moveToggle = animatedValue.interpolate({
    inputRange: [0, 1],
    outputRange: [2, 22],
  });

  useEffect(() => {
    setStatus(value);
  }, [value]);

  return (
    <View style={[styles.container]}>
      <TouchableOpacity
        style={[
          disabled
            ? styles.disabled
            : status
            ? styles.switchOn
            : styles.switchOff,
        ]}
        onPress={toggleSwitch}
        disabled={disabled}
        testID="toogle-switch-container-touchable-opacity"
      >
        <View style={styles.toggleContainer}>
          <Animated.View
            style={[
              styles.toggleWheelStyle,
              {
                marginLeft: moveToggle,
                marginRight: value ? 2 : 22,
              },
            ]}
          />
        </View>
      </TouchableOpacity>
    </View>
  );
};

ToogleSwitch.propTypes = {
  value: PropTypes.bool,
  disabled: PropTypes.bool,
};

ToogleSwitch.defaultProps = {
  value: true,
  disabled: false,
};

export { ToogleSwitch };
